prompt --application/shared_components/logic/application_processes/get_pending_reminders
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(1258216903218301)
,p_process_sequence=>2
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PENDING_REMINDERS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_cursor SYS_REFCURSOR;',
'BEGIN',
unistr('    -- \062C\0644\0628 \0627\0644\062A\0646\0628\064A\0647\0627\062A \0627\0644\062A\064A \062A\0645 \062A\062D\062F\064A\062B\0647\0627 \0628\0648\0627\0633\0637\0629 \0627\0644\0640 Job \0627\0644\062E\0644\0641\064A \0641\064A \0627\0644\062F\0642\064A\0642\0629 \0627\0644\0623\062E\064A\0631\0629'),
'    OPEN l_cursor FOR',
'        SELECT ',
'            NOTE_TITLE, ',
'            NOTE_DETAILS, ',
'            IMPORTANCE_LEVEL',
'        FROM USER_NOTES',
'        WHERE USER_ID = :APP_USER',
'          AND IS_SENT = ''Y''',
unistr('          AND LAST_UPDATED >= SYSDATE - (1/1440) -- \062A\0645 \062A\062D\062F\064A\062B\0647\0627 \0641\064A \0627\0644\062F\0642\064A\0642\0629 \0627\0644\0623\062E\064A\0631\0629 \0628\0648\0627\0633\0637\0629 \0627\0644\0640 Job'),
unistr('          AND REMINDER_DATETIME <= SYSDATE + (1/1440); -- \0644\0644\062A\0623\0643\062F \0645\0646 \0623\0646\0647\0627 \0644\0627 \062A\0632\0627\0644 \0636\0645\0646 \0646\0637\0627\0642 \0627\0644\062A\0646\0628\064A\0647'),
'',
'    APEX_JSON.WRITE(l_cursor);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>115078826
,p_created_on=>wwv_flow_imp.dz('20251222104547Z')
,p_updated_on=>wwv_flow_imp.dz('20260415093019Z')
,p_created_by=>'CHIRAZ'
,p_updated_by=>'CHIRAZ'
);
end;
