wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7556254928892842)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Nouveau'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   FOR rec IN (',
'      SELECT cc.id,',
'             cc.ref_ao,',
'             cc.objet_cct,',
'             cc.budget,',
'             cc.creer_par',
'      FROM cc',
'      WHERE cc.status = 5',
'        AND NOT EXISTS (',
'              SELECT 1 ',
'              FROM contrats ct ',
'              WHERE ct.id_cc = cc.id',
'        )',
'        AND EXISTS (',
'              SELECT 1',
'              FROM sp',
'              WHERE sp.id = cc.id',
unistr('                AND sp."\062A\0627\0631\064A\062E_\0642\0631\0627\0631__\0644\062C\0646\0629_\0627\0644\0635\0641\0642\0627\062A" + 5 < SYSDATE'),
'        )',
'   ) LOOP',
'      DECLARE',
'         v_count NUMBER;',
'      BEGIN',
unistr('         -- V\00E9rifier si une note existe d\00E9j\00E0 pour cet AO (peu importe l''user_id)'),
'         SELECT COUNT(*)',
'         INTO v_count',
'         FROM user_notes un',
'         WHERE un.note_title = ''Contrat manquant pour AO '' || rec.ref_ao;',
'',
'         IF v_count = 0 THEN',
'            -- Insertion pour le premier utilisateur',
'            INSERT INTO user_notes (',
'               user_id,',
'               note_title,',
'               note_details,',
'               reminder_datetime,',
'               importance_level',
'            ) VALUES (',
'               ''CONTRIBUTOR'',',
'               ''Contrat manquant pour AO '' || rec.ref_ao,',
'               ''Objet: '' || rec.objet_cct || '', Budget: '' || rec.budget,',
'               SYSDATE,',
'               3',
'            );',
'',
unistr('            -- Insertion pour le deuxi\00E8me utilisateur'),
'            INSERT INTO user_notes (',
'               user_id,',
'               note_title,',
'               note_details,',
'               reminder_datetime,',
'               importance_level',
'            ) VALUES (',
'               ''ADMINISTRATOR'',',
'               ''Contrat manquant pour AO '' || rec.ref_ao,',
'               ''Objet: '' || rec.objet_cct || '', Budget: '' || rec.budget,',
'               SYSDATE,',
'               3',
'            );',
'         END IF;',
'      END;',
'   END LOOP;',
'END;',
''))
