,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'MARK_REMINDER_SENT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_reminder_id NUMBER := APEX_APPLICATION.G_X01;',
'BEGIN',
'    UPDATE user_notes ',
'    SET is_sent = ''Y'',',
'        last_updated = SYSDATE',
'    WHERE id = l_reminder_id ',
'    AND user_id = :P0_MAT;',
'    ',
'    IF SQL%ROWCOUNT > 0 THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''success'');',
unistr('        apex_json.write(''message'', ''\062A\0645 \062A\062D\062F\064A\062B \062D\0627\0644\0629 \0627\0644\062A\0646\0628\064A\0647'');'),
'        apex_json.close_object;',
'    ELSE',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''error'');',
unistr('        apex_json.write(''message'', ''\0644\0645 \064A\062A\0645 \0627\0644\0639\062B\0648\0631 \0639\0644\0649 \0627\0644\062A\0646\0628\064A\0647'');'),
'        apex_json.close_object;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>24348184274119348
,p_created_on=>wwv_flow_imp.dz('20260205093336Z')
