,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' select CC.ID as ID,',
'    CC.REF_AO as REF_AO,',
'    CC.OBJET_CCT as OBJET_CCT,',
'    CC.BUDGET as BUDGET,',
unistr('    SP."\0637\0631\064A\0642\0629_\0627\0628\0631\0627\0645_\0627\0644\0635\0641\0642\0629" as "\0637\0631\064A\0642\0629_\0627\0628\0631\0627\0645_\0627\0644\0635\0641\0642\0629",'),
unistr('    SP."\0646\0648\0639\064A\0629_\0627\0644\0637\0644\0628" as "\0646\0648\0639\064A\0629_\0627\0644\0637\0644\0628",'),
unistr('    SP."\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629" as "\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629",'),
'    CC.NATURE_DE_DEPENSE as NATURE_DE_DEPENSE,',
unistr('    CC."D\00C9TAIL_DE_R\00C9PONSE" as "D\00C9TAIL_DE_R\00C9PONSE",'),
unistr('    CC."DATE_CR\00C9ATION" as "DATE_CR\00C9ATION",'),
unistr('    SP."\062A\0627\0631\064A\062E_\062A\0642\062F\064A\0645_\0643\0631\0627\0633\0627\062A_\0627\0644\0634\0631\0648\0637_\0644\0644\0645\0635\0627\062F\0642\0629" as "\062A\0627\0631\064A\062E_\062A\0642\062F\064A\0645_\0643\0631\0627\0633\0627\062A_\0627\0644\0634\0631\0648\0637_\0644\0644\0645\0635\0627\062F\0642\0629",'),
unistr('    SP."\062A\0627\0631\064A\062E_\0645\0635\0627\062F\0642\0629_\0627\0644\0644\062C\0646\0629_\0639\0644\0649_\0643\0631\0627\0633\0627\062A_\0627\0644\0634\0631\0648\0637" as "\062A\0627\0631\064A\062E_\0645\0635\0627\062F\0642\0629_\0627\0644\0644\062C\0646\0629_\0639\0644\0649_\0643\0631\0627\0633\0627\062A_\0627\0644\0634\0631\0648\0637",'),
unistr('    SP."\0627\0644\062A\0627\0631\064A\062E__\0644\0644\0625\0639\0644\0627\0646_\0639\0646_\0627\0644\0645\0646\0627\0641\0633\0629" as "\0627\0644\062A\0627\0631\064A\062E__\0644\0644\0625\0639\0644\0627\0646_\0639\0646_\0627\0644\0645\0646\0627\0641\0633\0629",'),
unistr('    CC."DATE_LIMITE_PROPOS\00C9E" as "DATE_LIMITE_PROPOS\00C9E",'),
'    CC.DATE_OUVERTURE_DES_PLIS as DATE_OUVERTURE_DES_PLIS,',
unistr('    SP."\062A\0627\0631\064A\062E_\0642\0631\0627\0631__\0644\062C\0646\0629_\0627\0644\0635\0641\0642\0627\062A" as "\062A\0627\0631\064A\062E_\0642\0631\0627\0631__\0644\062C\0646\0629_\0627\0644\0635\0641\0642\0627\062A",'),
'    CC.STATUS as STATUS,',
unistr('    SP."\062A\0627\0631\064A\062E_\0627\0631\062C\0627\0639_\0627\0644\0636\0645\0627\0646\0627\062A_\0627\0644\0648\0642\062A\064A\0629" as "\062A\0627\0631\064A\062E_\0627\0631\062C\0627\0639_\0627\0644\0636\0645\0627\0646\0627\062A_\0627\0644\0648\0642\062A\064A\0629",'),
unistr('    SP."\0627\0644\0645\0643\0644\0641_\0628\0627\0644\0645\0644\0641" as "\0627\0644\0645\0643\0644\0641_\0628\0627\0644\0645\0644\0641",'),
unistr('     case when SP."\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629" = ''CRA'' then 40 else 4 end as P,'),
unistr('    case when SP."\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629" = ''CRA'' then ''P40_ID_1'' else ''P4_ID_1'' end as VID1,'),
unistr('    case when SP."\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629" = ''CRA'' then ''P40_ID_2'' else ''P4_ID_2'' end as VID2,'),
unistr('    case when SP."\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629" = ''CRA'' then ''P40_ID'' else ''P4_ID'' end as VID,'),
'    fl.ID as FL_ID,',
'    fl.ID_CC ',
' from FICHIER_LNCEMENT fl,',
'    SP SP,',
'    CC CC ',
' where (CC.ID=SP.ID',
'    and CC.ID=fl.ID_CC)',
' and ',
' ',
' ',
'',
' ',
'    -- Condition 2 : Sinon, on filtre sur le champ',
unistr('    "\0627\0644\0645\0643\0644\0641_\0628\0627\0644\0645\0644\0641" = v(''P0_USER'')'),
'',
'AND  CC.STATUS <''5''',
