wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(33558881575477424142)
,p_name=>unistr('Enregistrements ma\00EEtre')
,p_template=>3371237801798025892
,p_display_sequence=>40
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#:t-Form--large:t-Form--stretchInputs'
,p_component_template_options=>'t-MediaList--showIcons:t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH summary AS (',
'    SELECT ',
'        MIN("ID") as ID,',
'        "REF_AO",',
unistr('        -- On concat\00E8ne les contrats ici'),
'        LISTAGG("N_CONTRAT_BC", '', '') WITHIN GROUP (ORDER BY "N_CONTRAT_BC") as TOUS_LES_CONTRATS,',
'        COUNT(*) as NB_CONTRATS',
'    FROM "CONTRATS"',
'    GROUP BY "REF_AO"',
')',
'SELECT ',
'    ID,',
'    NULL LINK_CLASS,',
'    apex_page.get_url(p_items => ''P30_ID'', p_values => ID) LINK,',
'    NULL ICON_CLASS,',
'    NULL LINK_ATTR,',
'    NULL ICON_COLOR_CLASS,',
'    CASE WHEN COALESCE(:P30_ID, ''0'') = TO_CHAR(ID) THEN ''is-active'' ELSE '' '' END LIST_CLASS,',
'    -- Titre : REF_AO avec tronquage si trop long',
'    CASE WHEN LENGTH("REF_AO") > 50 THEN SUBSTR("REF_AO", 1, 50) || ''...'' ELSE "REF_AO" END LIST_TITLE,',
'    -- Texte : Liste des contrats',
'    CASE WHEN LENGTH(TOUS_LES_CONTRATS) > 100 THEN SUBSTR(TOUS_LES_CONTRATS, 1, 100) || ''...'' ELSE TOUS_LES_CONTRATS END LIST_TEXT,',
'    NB_CONTRATS LIST_BADGE',
'FROM summary',
'WHERE (:P30_SEARCH IS NULL',
'    OR UPPER("REF_AO") LIKE ''%''||UPPER(:P30_SEARCH)||''%''',
'    OR UPPER(TOUS_LES_CONTRATS) LIKE ''%''||UPPER(:P30_SEARCH)||''%''',
')',
'ORDER BY "REF_AO"'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P30_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>2093604263195414824
