,p_component_template_options=>'#DEFAULT#:t-MediaList--showBadges:u-colors:t-MediaList--horizontal:t-Report--hideNoPagination'
,p_item_display_point=>'BELOW'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "REF_AO",',
'"ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P30_ID'', p_values => "ID") LINK, ',
'    apex_page.get_url(p_items => ''P30_REF'', p_values => "REF_AO") LINK2,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P30_ID,''0'') = "ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("N_CONTRAT_BC", 1, 50)||( case when length("N_CONTRAT_BC") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("REF_AO", 1, 50)||( case when length("REF_AO") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "CONTRATS" x',
'where ( upper(x."REF_AO") like ''%''||upper(:P30_REF)||''%'' ) -- "REF_AO" = :P30_REF',
'order by "REF_AO"',
''))
,p_display_when_condition=>'P30_ID'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_header=>'&REF_AO.'
