wwv_flow_imp_page.create_page(
 p_id=>32
,p_name=>'Gestion des Rappels'
,p_alias=>'GESTION-DES-RAPPELS'
,p_step_title=>'Gestion des Rappels'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// 1. \0637\0644\0628 \0627\0644\0625\0630\0646 \0644\062A\0646\0628\064A\0647\0627\062A \0627\0644\0640 Windows'),
'function requestNotificationPermission() {',
'    if (''Notification'' in window &&',
'        Notification.permission !== ''granted'' &&',
'        Notification.permission !== ''denied'') {',
'        Notification.requestPermission();',
'    }',
'}',
'',
unistr('// 2. \062A\0646\0628\064A\0647\0627\062A \0645\0633\062A\0645\0631\0629 \062D\062A\0649 \0627\0646\062A\0647\0627\0621 \0627\0644\0645\0648\0639\062F (\062A\0639\0645\0644 \0639\0646\062F \0627\0644\0646\062F\0627\0621)'),
'function checkAndDisplayReminders() {',
'    apex.server.process(''GET_PENDING_REMINDERS'', {',
'        x01: ''Check''',
'    }, {',
'        dataType: "json",',
'        success: function (pData) {',
'            if (pData && pData.items && pData.items.length > 0) {',
'                pData.items.forEach(function (item) {',
'                    var title = item.NOTE_TITLE;',
'                    var details = item.NOTE_DETAILS;',
'                    var importance = item.IMPORTANCE_LEVEL;',
'',
'                    if (importance == 3) {',
unistr('                        // \D83D\DD34 \0645\0647\0645 \062C\062F\0627\064B: Native Notification'),
'                        if (Notification.permission === "granted") {',
unistr('                            new Notification("\D83D\DEA8 \062A\0630\0643\064A\0631 \0645\0633\062A\0645\0631: " + title, {'),
unistr('                                body: details + "\005Cn(\0633\064A\0633\062A\0645\0631 \062D\062A\0649 \0627\0644\0645\0648\0639\062F \0627\0644\0646\0647\0627\0626\064A)",'),
'                                icon: "data:image/svg+xml;utf8,",',
'                                badge: "data:image/svg+xml;utf8,"',
'                            });',
'                        }',
'                    } else if (importance == 2) {',
unistr('                        // \D83D\DFE0 \0645\0647\0645: Popup'),
unistr('                        apex.message.showPageSuccess("\D83D\DD14 \062A\0630\0643\064A\0631 \0645\0633\062A\0645\0631: " + title + "<br>" + details);'),
'                    } else if (importance == 1) {',
unistr('                        // \D83D\DD35 \0639\0627\062F\064A: \0625\0634\0639\0627\0631 \062E\0641\064A\0641'),
'                        apex.message.clearErrors();',
unistr('                        apex.message.showPageSuccess("\D83D\DCDD " + title);'),
'                    }',
'                });',
'            }',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
unistr('            console.error("\062E\0637\0623 \0641\064A \062C\0644\0628 \0627\0644\062A\0646\0628\064A\0647\0627\062A:", textStatus);'),
'        }',
'    });',
'}',
'',
unistr('// 3. \062A\0637\0628\064A\0642 \0627\0644\0646\0633\0628\0629 \0627\0644\0645\0626\0648\064A\0629 \0639\0644\0649 \0634\0631\064A\0637 \0627\0644\062A\0642\062F\0645 \062F\0627\062E\0644 \0627\0644\0640 Badge'),
'function applyProgressWidth() {',
'    document.querySelectorAll(''#reminders_cards .a-CardView-badge'').forEach(function (badge) {',
'        var text = badge.innerText || badge.textContent;',
unistr('        // \0645\062B\0627\0644 \0646\0635: "15 \062F\0642\064A\0642\0629 (40%)" \0623\0648 "\D83D\DD04 \062A\0630\0643\064A\0631 \0645\0633\062A\0645\0631 (70%)"'),
'        var match = text.match(/\((\d+)%\)/);',
'        if (match && match[1]) {',
'            var percent = match[1];',
'            badge.style.setProperty(''--progress-width'', percent + ''%'');',
'        }',
'    });',
'}',
'',
unistr('// 4. \062A\062D\062F\064A\062B \0643\0631\0648\062A \0627\0644\062A\0630\0643\064A\0631 + \0627\0644\0634\0631\064A\0637'),
'function refreshRemindersCards() {',
'    try {',
'        var reg = apex.region(''reminders_cards'');',
'        if (reg) {',
'            reg.refresh();',
unistr('            // \0628\0639\062F \0623\0646 \064A\0646\062A\0647\064A \0627\0644\0640 refresh \0646\0637\0628\0651\0642 \0627\0644\0646\0633\0628\0629 \0639\0644\0649 \0627\0644\0628\0627\062F\062C\0627\062A'),
'            setTimeout(applyProgressWidth, 500);',
'        }',
'    } catch (e) {',
'        console.error(''Refresh error:'', e);',
'    }',
'}',
'',
unistr('// 5. \062A\0634\063A\064A\0644 \0643\0644 \0634\064A\0621 \0639\0646\062F \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629'),
'requestNotificationPermission();',
unistr('checkAndDisplayReminders();   // \0641\062D\0635 \0641\0648\0631\064A \0623\0648\0644 \0645\0631\0629'),
unistr('refreshRemindersCards();      // \062A\062D\062F\064A\062B \0627\0644\0643\0631\0648\062A \0623\0648\0644 \0645\0631\0629'),
'',
unistr('// \062A\0646\0628\064A\0647\0627\062A + \062A\062D\062F\064A\062B \0643\0631\0648\062A \0643\0644 30 \062B\0627\0646\064A\0629'),
'setInterval(function () {',
'    checkAndDisplayReminders();',
'    refreshRemindersCards();',
unistr('}, 30000); // 30000 ms = 30 \062B\0627\0646\064A\0629'),
''))
