);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7557293784892853)
,p_process_sequence=>20
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get_User_Role'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT role_static_id',
'  INTO :P32_ROLE',
'  FROM apex_appl_acl_user_roles',
' WHERE application_id = :APP_ID',
'   AND user_name = :APP_USER',
unistr(' FETCH FIRST 1 ROW ONLY; -- S\00E9curit\00E9 si l''utilisateur a plusieurs r\00F4les')))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>24330222641495317
,p_created_on=>wwv_flow_imp.dz('20260205130732Z')
,p_updated_on=>wwv_flow_imp.dz('20260205130755Z')
,p_created_by=>'CHIRAZ'
,p_updated_by=>'CHIRAZ'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1308093084129439)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'MARK_REMINDER_SENT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_reminder_id NUMBER := APEX_APPLICATION.G_X01;',
'BEGIN',
'    UPDATE user_notes ',
'    SET is_sent = ''Y'',',
'        last_updated = SYSDATE',
'    WHERE id = l_reminder_id ',
'    AND user_id = :APP_USER;',
'    ',
'    IF SQL%ROWCOUNT > 0 THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''success'');',
unistr('        apex_json.write(''message'', ''\062A\0645 \062A\062D\062F\064A\062B \062D\0627\0644\0629 \0627\0644\062A\0646\0628\064A\0647'');'),
'        apex_json.close_object;',
'    ELSE',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''error'');',
unistr('        apex_json.write(''message'', ''\0644\0645 \064A\062A\0645 \0627\0644\0639\062B\0648\0631 \0639\0644\0649 \0627\0644\062A\0646\0628\064A\0647'');'),
'        apex_json.close_object;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>18081021940731903
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1308187886129440)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PENDING_REMINDERS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    apex_json.open_object;',
'    apex_json.open_array(''items'');',
'',
'    FOR r IN (',
'        SELECT id, note_title, note_details, importance_level',
'        FROM user_notes',
'        WHERE user_id = :APP_USER',
unistr('        AND reminder_datetime - (NVL(pre_reminder_mins,0)/1440) <= SYSDATE  -- \062D\0627\0646 \0648\0642\062A \0627\0644\062A\0646\0628\064A\0647'),
unistr('        AND reminder_datetime >= SYSDATE - 1/24  -- \0627\0644\0645\0648\0639\062F \0644\0645 \064A\0646\062A\0647\0650 \062A\0645\0627\0645\0627\064B (\0622\062E\0631 \0633\0627\0639\0629)'),
'        AND rownum <= 10',
'    )',
'    LOOP',
'        apex_json.open_object;',
'        apex_json.write(''ID'', r.id);',
'        apex_json.write(''NOTE_TITLE'', r.note_title);',
'        apex_json.write(''NOTE_DETAILS'', r.note_details);',
'        apex_json.write(''IMPORTANCE_LEVEL'', r.importance_level);',
'        apex_json.close_object;',
'    END LOOP;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>18081116742731904
);
end;
