wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4146125082107390)
,p_plug_name=>unistr('\062C\062F\0648\0644 \0627\0644\0627\0634\063A\0627\0644')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_plug_grid_column_css_classes=>'myClass'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT s.ID,',
unistr('       s."\0627\0644\0643\0644\0641\0629_\0627\0644\062A\0642\062F\064A\0631\064A\0629",'),
unistr('       s."\0646\0648\0639\064A\0629_\0627\0644\0637\0644\0628",'),
unistr('       s."\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629",'),
unistr('       s."\0627\0644\0627\062C\0631\0627\0621\0627\062A",'),
unistr('       s."\0637\0631\064A\0642\0629_\0627\0628\0631\0627\0645_\0627\0644\0635\0641\0642\0629",'),
unistr('       s."\0622\062C\0627\0644_\0627\0644\0627\0646\062C\0627\0632",'),
unistr('       s."\0627\0644\0645\0643\0644\0641_\0628\0627\0644\0645\0644\0641",'),
unistr('       s."\0631\0642\0645_\0627\0644\0627\0633\062A\0634\0627\0631\0629",'),
unistr('       s."\062A\0627\0631\064A\062E_\0628\062F\0627\064A\0629_\0645\0639\0627\0644\062C\0629_\0627\0644\0645\0644\0641_\0627\0644\062C\062F\064A\062F",'),
'       CASE ',
'         WHEN c.REF_AO IS NOT NULL  THEN ''OK''',
unistr('         WHEN  c.REF_AO IS  NULL  AND s."\062A\0627\0631\064A\062E_\0628\062F\0627\064A\0629_\0645\0639\0627\0644\062C\0629_\0627\0644\0645\0644\0641_\0627\0644\062C\062F\064A\062F" < SYSDATE THEN ''WAIT'''),
'        ',
'         ELSE ''KO''',
'       END AS ETAT,',
unistr('       s."\0627\0644\062A\0627\0631\064A\062E_\0646\0647\0627\064A\0629_\0627\0644\0639\0642\062F_\0627\0644\062C\0627\0631\064A",'),
unistr('       s."\0645\0648\0636\0648\0639_\0627\0644\0635\0641\0642\0629",'),
'       s.ANNEE',
'FROM SUIVI s',
'LEFT JOIN CC c',
unistr('       ON c.REF_AO = s."\0631\0642\0645_\0627\0644\0627\0633\062A\0634\0627\0631\0629"'),
'    WHERE s.ANNEE = :P34_ANNEE   ;',
''))
,p_plug_source_type=>'NATIVE_IG'
