,p_name=>unistr('Enregistrements ma\00EEtre')
,p_template=>3371237801798025892
,p_display_sequence=>20
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_03'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select DISTINCT',
'    "ANNEE",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P34_ANNEE'', p_values => "ANNEE") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P34_ANNEE,''0'') = "ANNEE"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
unistr('    "ANNEE" LIST_TITLE, -- Puisque c''est group\00E9, on affiche juste l''ann\00E9e'),
unistr('    null LIST_TEXT,     -- On met NULL ici car on ne peut pas afficher un texte sp\00E9cifique si plusieurs lignes sont combin\00E9es'),
'    null LIST_BADGE',
'from "SUIVI" x',
'where (',
'        upper(x."ANNEE") like ''%''||upper(:P34_SEARCH)||''%''',
'        ',
'      )',
'order by "ANNEE"'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>':P34_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>2093604263195414824
