,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_dialog_resizable=>'Y'
,p_protection_level=>'C'
,p_page_component_map=>'02'
,p_created_on=>wwv_flow_imp.dz('20260331110312Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260410153403Z')
,p_created_by=>'CHIRAZ'
,p_last_updated_by=>'CHIRAZ'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(14280876255979837)
,p_plug_name=>'edit-contrat'
,p_title=>'&P36_N_CONTRAT_BC.'
,p_region_css_classes=>'u-color-19-contrast'
,p_icon_css_classes=>'fa-volume-control-phone'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4501440665235496320
,p_plug_display_sequence=>10
,p_plug_grid_row_css_classes=>'-u-color-14-contrast'
,p_plug_grid_column_css_classes=>'u-color-14-contrast'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select CONTRATS.ID as ID,',
'    CONTRATS.ID_CC as ID_CC,',
'    CONTRATS.N_CONTRAT_BC as N_CONTRAT_BC,',
unistr('    CONTRATS."TITULAIRE_DU_MARCH\00C9" as "TITULAIRE_DU_MARCH\00C9",'),
'    CONTRATS.REF_AO as REF_AO,',
'    CONTRATS.OBJET as OBJET,',
'    CONTRATS.CADRE__PONCTUEL as CADRE__PONCTUEL,',
'    CONTRATS.MONTANT as MONTANT,',
'    CONTRATS.DEVISE as DEVISE,',
'    CONTRATS.DATE_DE_MISE_VIGUEUR as DATE_DE_MISE_VIGUEUR,',
unistr('    CONTRATS."DATE_FIN_DU_MARCH\00C9" as "DATE_FIN_DU_MARCH\00C9",'),
'    CONTRATS.MONTANT_DE_LA_CAUTION as MONTANT_DE_LA_CAUTION,',
unistr('    CONTRATS."DATE_DE_MAIN_LEV\00C9E" as "DATE_DE_MAIN_LEV\00C9E",'),
'    CONTRATS.N__COMMISSION as N__COMMISSION,',
'    CONTRATS.ETAT as ETAT,',
'    CONTRATS.OBSERVATION_ as OBSERVATION_,',
'    CONTRATS.COL016 as COL016,',
'    CONTRATS.DEMANDEUR as DEMANDEUR,',
'    CONTRATS.RESPONSABLE as RESPONSABLE,',
unistr('    CONTRATS."DATE_DE_LA_PREMI\00C8RE_PI\00C8CE_L\00C9GALE" as "DATE_DE_LA_PREMI\00C8RE_PI\00C8CE_L\00C9GALE",'),
unistr('    CONTRATS."DATE_DE_LA_DERNI\00C8RE_PI\00C8CE_L\00C9GALE" as "DATE_DE_LA_DERNI\00C8RE_PI\00C8CE_L\00C9GALE",'),
'    CONTRATS.N__ARCHIVAGE as N__ARCHIVAGE,',
'    CONTRATS.DATE_DE_L_ARCHIVAGE as DATE_DE_L_ARCHIVAGE,',
'    CONTRATS.N__RANG_ARCHIVAGE as N__RANG_ARCHIVAGE,',
'    CONTRATS.OBSERVATION as OBSERVATION,',
'    CONTRATS.DATE_LIVRAISON_JURIDIQUE as DATE_LIVRAISON_JURIDIQUE,',
'    CONTRATS.DATE_AVIS_JURIDIQUE as DATE_AVIS_JURIDIQUE,',
'    CONTRATS.DATE_ENVOI_CLIENT_SIGNATURE as DATE_ENVOI_CLIENT_SIGNATURE,',
'    CONTRATS.DATE_RETOUR_CLIENT_SIGNE as DATE_RETOUR_CLIENT_SIGNE,',
'    CONTRATS.DATE_ENVOI_ADMIN_SIGNATURE as DATE_ENVOI_ADMIN_SIGNATURE,',
'    CONTRATS.DATE_RETOUR_ADMIN_SIGNE as DATE_RETOUR_ADMIN_SIGNE,',
'    CONTRATS.DATE_ENVOI_CLIENT_ENREGISTREMENT as DATE_ENVOI_CLIENT_ENREGISTREMENT,',
'    CONTRATS.DATE_RETOUR_ENREGISTRE as DATE_RETOUR_ENREGISTRE,',
'    CONTRATS.DATE_GARANTIE_FINALE as DATE_GARANTIE_FINALE,',
'    CASE',
unistr('      WHEN DATE_FIN_DU_MARCH\00C9 IS NOT NULL '),
unistr('         AND DATE_FIN_DU_MARCH\00C9 < SYSDATE'),
unistr('    THEN ''Cl\00F4tur\00E9''   '),
'     WHEN DATE_DE_MISE_VIGUEUR <=  SYSDATE',
unistr('         AND (DATE_FIN_DU_MARCH\00C9 IS NULL '),
unistr('              OR DATE_FIN_DU_MARCH\00C9 <= SYSDATE)'),
unistr('               THEN ''En ex\00E9cution'''),
unistr('    WHEN DATE_GARANTIE_FINALE IS NOT NULL THEN ''Cautionnement D\00E9finitif re\00E7ue'''),
unistr('    WHEN DATE_RETOUR_ENREGISTRE IS NOT NULL THEN ''Contrat enregistr\00E9'''),
'    WHEN DATE_ENVOI_CLIENT_ENREGISTREMENT IS NOT NULL THEN ''Enregistrement en cours''',
unistr('    WHEN DATE_RETOUR_ADMIN_SIGNE IS NOT NULL THEN ''Sign\00E9 par administration'''),
'    WHEN DATE_ENVOI_ADMIN_SIGNATURE IS NOT NULL THEN ''En attente signature administration''',
unistr('    WHEN DATE_RETOUR_CLIENT_SIGNE IS NOT NULL THEN ''Sign\00E9 par titulaire'''),
'    WHEN DATE_ENVOI_CLIENT_SIGNATURE IS NOT NULL THEN ''En attente signature titulaire''',
unistr('    WHEN DATE_AVIS_JURIDIQUE IS NOT NULL THEN ''Avis juridique re\00E7u'''),
'    WHEN DATE_LIVRAISON_JURIDIQUE IS NOT NULL THEN ''En cours avis juridique''',
'',
'   ',
'    ',
unistr('    ELSE ''Nouveau / Non trait\00E9'''),
'END AS etat_contrat,',
'  CASE',
unistr('      WHEN "DATE_FIN_DU_MARCH\00C9" IS NOT NULL '),
unistr('         AND "DATE_FIN_DU_MARCH\00C9" < SYSDATE'),
'    THEN  ''11''   ',
'     WHEN CONTRATS.DATE_DE_MISE_VIGUEUR <=  SYSDATE',
unistr('         AND (CONTRATS."DATE_FIN_DU_MARCH\00C9" IS NULL '),
unistr('              OR CONTRATS."DATE_FIN_DU_MARCH\00C9" <= SYSDATE) THEN ''10'''),
'',
'    WHEN DATE_GARANTIE_FINALE IS NOT NULL THEN ''9''',
'    WHEN DATE_RETOUR_ENREGISTRE IS NOT NULL THEN ''8''',
'    WHEN DATE_ENVOI_CLIENT_ENREGISTREMENT IS NOT NULL THEN ''7''',
'    WHEN DATE_RETOUR_ADMIN_SIGNE IS NOT NULL THEN ''6''',
'    WHEN DATE_ENVOI_ADMIN_SIGNATURE IS NOT NULL THEN ''5''',
'    WHEN DATE_RETOUR_CLIENT_SIGNE IS NOT NULL THEN ''4''',
'    WHEN DATE_ENVOI_CLIENT_SIGNATURE IS NOT NULL THEN ''3''',
'    WHEN DATE_AVIS_JURIDIQUE IS NOT NULL THEN ''2''',
'    WHEN DATE_LIVRAISON_JURIDIQUE IS NOT NULL THEN ''1''',
'',
'   ',
'    ',
'    ELSE ''0''',
'END AS etat_cont,',
'',
'',
'',
'    CONTRATS.RESPONSABLE_DOS as RESPONSABLE_DOS ',
' from CONTRATS CONTRATS'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_add_authorization_scheme=>wwv_flow_imp.id(74585100534688929216)
,p_delete_authorization_scheme=>wwv_flow_imp.id(74585100534688929216)
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
,p_created_on=>wwv_flow_imp.dz('20260331110312Z')
,p_updated_on=>wwv_flow_imp.dz('20260410150626Z')
,p_created_by=>'CHIRAZ'
,p_updated_by=>'CHIRAZ'
);
