,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    CASE code',
unistr('        WHEN ''USD'' THEN ''\D83D\DCB5 Dollar (USD)'''),
unistr('        WHEN ''EUR'' THEN ''\D83D\DCB6 Euro (EUR)'''),
unistr('        WHEN ''TND'' THEN ''\D83C\DDF9\D83C\DDF3 Dinar (TND)'''),
unistr('        ELSE ''\D83D\DCB0 Autre'''),
'    END as display_value,',
'    code as return_value',
'FROM (',
'    SELECT ''USD'' as code FROM dual UNION ALL',
'    SELECT ''EUR'' FROM dual UNION ALL',
'    SELECT ''TND'' FROM dual UNION ALL',
'    SELECT ''OTHER'' FROM dual',
')'))
