,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    cc.id,',
'    cc.ref_ao,',
'    cc.objet_cct,',
'    cc.budget,',
unistr('    cc."D\00C9TAIL_DE_R\00C9PONSE",'),
'    cc.nature_de_depense,',
unistr('    cc."DATE_LIMITE_PROPOS\00C9E",'),
'    cc.date_de_lanc,',
'    cc.pv_cct,',
'    cc.programme_ouverture_de_plis,',
'    cc.jours_rest,',
'    cc.date_ouverture_des_plis,',
'    cc.status,',
'    cc.creer_par,',
unistr('    cc."DATE_CR\00C9ATION",'),
'    cc.programme_de_lancement',
'FROM cc',
'WHERE cc.status = 5',
'',
'  AND NOT EXISTS (',
'        SELECT 1',
'        FROM contrats ct',
'        WHERE ct.id_cc = cc.id',
'  );',
''))
