wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(33554589905354742607)
,p_name=>unistr('Enregistrements ma\00EEtre')
,p_template=>3371237801798025892
,p_display_sequence=>40
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_03'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select DISTINCT',
'    "ANNEE",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P41_ANNE'', p_values => "ANNEE") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P41_ANNE,''0'') = "ANNEE"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
unistr('    "ANNEE" LIST_TITLE, -- Puisque c''est group\00E9, on affiche juste l''ann\00E9e'),
unistr('    null LIST_TEXT,     -- On met NULL ici car on ne peut pas afficher un texte sp\00E9cifique si plusieurs lignes sont combin\00E9es'),
'    null LIST_BADGE',
'from "PREVIS_ANNUEL" x',
'where (:P41_SEARCH is null',
'        or upper(x."ANNEE") like ''%''||upper(:P41_SEARCH)||''%''',
'      )',
