,p_process_sequence=>50
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert_Into_3_Tables'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_cc_id NUMBER;',
'BEGIN',
unistr('    -- 1. Insertion dans CC (ID g\00E9n\00E9r\00E9 automatiquement)'),
'    INSERT INTO CC (',
'        REF_AO,',
'       OBJET_CCT,',
'    ',
'       BUDGET,',
unistr('       D\00C9TAIL_DE_R\00C9PONSE,'),
'       NATURE_DE_DEPENSE,',
unistr('        DATE_CR\00C9ATION,'),
'        CREER_PAR,',
'        PV_CCT,',
'        STATUS',
'        ',
'    ) VALUES (',
'        v(''P42_DR''),',
unistr('        v(''P42_\0645\0648\0636\0648\0639_\0627\0644\0635\0641\0642\0629''),'),
'',
unistr('        v(''P42_\0627\0644\0643\0644\0641\0629_\0627\0644\062A\0642\062F\064A\0631\064A\0629''),'),
unistr('        v(''P42_\0622\062C\0627\0644_\0627\0644\0627\0646\062C\0627\0632''),'),
'        ''Exploitation'',',
'        SYSDATE,',
'        :P42_CREER_PAR,',
'        ''Y'',',
'        ''1''',
unistr('    ) RETURNING ID INTO v_cc_id;  -- R\00E9cup\00E8re l''ID g\00E9n\00E9r\00E9'),
'    ',
unistr('    -- 2. Insertion dans SP avec le m\00EAme ID que CC'),
'    INSERT INTO SP (',
'        ID,',
unistr('          \0639\062F\062F,'),
unistr('    \0637\0631\064A\0642\0629_\0627\0628\0631\0627\0645_\0627\0644\0635\0641\0642\0629,'),
unistr('    \0646\0648\0639\064A\0629_\0627\0644\0637\0644\0628,'),
unistr('    \0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629,'),
unistr('    \062A\0627\0631\064A\062E_\0648\0631\0648\062F_CPT_\0645\0645\0636\0627\0629,'),
unistr('    \0627\0644\0645\0643\0644\0641_\0628\0627\0644\0645\0644\0641'),
'    ) VALUES (',
unistr('        v_cc_id,  -- Utilise l''ID r\00E9cup\00E9r\00E9 de CC'),
'         v(''P42_DR''),',
unistr('    v(''P42_\0637\0631\064A\0642\0629_\0627\0628\0631\0627\0645_\0627\0644\0635\0641\0642\0629_1''),'),
unistr('     v(''P42_\0646\0648\0639\064A\0629_\0627\0644\0637\0644\0628_1''),'),
unistr('    v(''P42_\0627\0644\0644\062C\0646\0629_\0627\0644\0645\062E\062A\0635\0629_1''),'),
unistr('    v(''P42_\062A\0627\0631\064A\062E_\0628\062F\0627\064A\0629_\0645\0639\0627\0644\062C\0629_\0627\0644\0645\0644\0641_\0627\0644\062C\062F\064A\062F''),'),
unistr('       v(''P42_\0627\0644\0645\0643\0644\0641_\0628\0627\0644\0645\0644\0641_1'')'),
'    );',
'    ',
'',
'',
'  ',
'    -- 3. Insertion dans FICHIER_DE_LANCEMENT avec IDCC',
'    INSERT INTO FICHIER_LNCEMENT (',
'               ID_CC,',
'       PROPOSITION_COMMISSION,',
'       CC_POUR_LANCEMENT,',
'       CRITERES_EVALUATION,',
'       AVIS_DE_PRESSE,',
'      DESIGNATION_DE_LA_COMMISSION,',
'         MAIL_PRESTATAIRE,',
'      PROGRAMME_OUVERTURE_DE_PLIS,',
'      NOTE_OUVERTURE_PLIS,',
'      CAUTION_P',
'     )',
'VALUES (',
unistr('     v_cc_id,  -- Utilise l''ID r\00E9cup\00E9r\00E9 de CC'),
'    ''N'',',
'    ''N'',',
'    ''N'',',
'    ''N'',',
'    ''N'',',
'    ''N'',',
'    ''N'',',
'    ''N'',',
'    ''N''',
'     ',
'    );',
'    ',
'    -- Commit de la transaction',
'    COMMIT;',
'    ',
unistr('    -- Message de succ\00E8s avec l''ID g\00E9n\00E9r\00E9'),
'    apex_application.g_print_success_message := ',
unistr('        ''Enregistrement r\00E9ussi. ID g\00E9n\00E9r\00E9 : '' || v_cc_id;'),
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        -- Annulation de toutes les insertions en cas d''erreur',
'        ROLLBACK;',
'        ',
'        -- Affichage de l''erreur',
'        apex_error.add_error(',
'            p_message => ''Erreur lors de l''''insertion : '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'        ',
unistr('        -- Relance l''exception pour arr\00EAter le traitement'),
'        RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(4259358448146496)
,p_internal_uid=>20900952406342847
,p_created_on=>wwv_flow_imp.dz('20260126123952Z')
,p_updated_on=>wwv_flow_imp.dz('20260415135525Z')
,p_created_by=>'CHIRAZ'
,p_updated_by=>'CHIRAZ'
);
end;
