,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'Refresh Interval: 600'
,p_plug_template=>2674017834225413037
,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    cc.id,',
'    cc.ref_ao,',
'    cc.objet_cct,',
'    cc.budget,',
unistr('    cc."D\00C9TAIL_DE_R\00C9PONSE",'),
'    cc.nature_de_depense,',
unistr('    cc."DATE_LIMITE_PROPOS\00C9E",'),
'    cc.date_de_lanc,',
'    cc.pv_cct,',
'    cc.programme_ouverture_de_plis,',
'    cc.jours_rest,',
'    cc.date_ouverture_des_plis,',
'    cc.status,',
'    case ',
unistr('    WHEN  sysdate - cc.date_ouverture_des_plis > = 30 THEN  ''\0644\0642\062F \0645\0631  '' || FLOOR(sysdate - cc.date_ouverture_des_plis) || ''   \064A\0648\0645\0627 \0639\0644\0649 \0641\062A\062D \0627\0644\0639\0631\0648\0636 \0648 \0644\0642\062F \062A\0645\062A \0645\0639\0627\0644\062C\0629 \0627\0644\0645\0644\0641 \0648 \0625\0631\062C\0627\0639 \0627\0644\0636\0645\0627\0646\0627\062A \0627\0644\0648\0642\062A\064A\0629 \0627\0644\0631\062C\0627\0621 \0625\062F\062E\0627\0644 \0627\0644\0645\0639\0637\064A\0627\062A \0627\0644\062E\0627\0635\0629 \0628\0627\0644\0639\0642\0648\062F \0648 \0630\0644\0643 \0628\0627\0644\0636\063A\0637 \0639\0644\0649 \0627\0644\0631')
||unistr('\0627\0628\0637 \0623\0633\0641\0644 \0647\0630\0627 \0627\0644\062A\0646\0628\064A\0647   '''),
unistr('        WHEN  sysdate - cc.date_ouverture_des_plis > 20 and  sysdate - cc.date_ouverture_des_plis < 30 THEN ''\0644\0642\062F \0645\0631  '' || FLOOR(sysdate - cc.date_ouverture_des_plis) || ''   \064A\0648\0645\0627 \0639\0644\0649 \0641\062A\062D \0627\0644\0639\0631\0648\0636 \0648 \0644\0642\062F \062A\0645\062A \0645\0639\0627\0644\062C\0629 \0627\0644\0645\0644\0641 \0648 \0625\0631\062C\0627\0639 \0627\0644\0636\0645\0627\0646\0627\062A \0627\0644\0648\0642\062A\064A\0629 \0627\0644\0631\062C\0627\0621 \0625\062F')
||unistr('\062E\0627\0644 \0627\0644\0645\0639\0637\064A\0627\062A \0627\0644\062E\0627\0635\0629 \0628\0627\0644\0639\0642\0648\062F ( \0625\0646 \062A\0648\0641\0631\062A ) \0648 \0630\0644\0643 \0628\0627\0644\0636\063A\0637 \0639\0644\0649 \0627\0644\0631\0627\0628\0637 \0623\0633\0641\0644 \0647\0630\0627 \0627\0644\062A\0646\0628\064A\0647   '''),
unistr('        WHEN sysdate - cc.date_ouverture_des_plis > 0 and  sysdate - cc.date_ouverture_des_plis < 20 THEN  ''\0644\0642\062F \0645\0631\062A '' || FLOOR(sysdate - cc.date_ouverture_des_plis) || ''   \0623\064A\0627\0645 \0639\0644\0649 \0641\062A\062D \0627\0644\0639\0631\0648\0636 \0648 \0644\0642\062F \062A\0645\062A \0645\0639\0627\0644\062C\0629 \0627\0644\0645\0644\0641 \0648 \0625\0631\062C\0627\0639 \0627\0644\0636\0645\0627\0646\0627\062A \0627\0644\0648\0642\062A\064A\0629 \0627\0644\0631\062C\0627\0621 \0625\062F\062E')
||unistr('\0627\0644 \0627\0644\0645\0639\0637\064A\0627\062A \0627\0644\062E\0627\0635\0629 \0628\0627\0644\0639\0642\0648\062F ( \0625\0646 \062A\0648\0641\0631\062A ) \0648 \0630\0644\0643 \0628\0627\0644\0636\063A\0637 \0639\0644\0649 \0627\0644\0631\0627\0628\0637 \0623\0633\0641\0644 \0647\0630\0627 \0627\0644\062A\0646\0628\064A\0647   '''),
unistr('        ELSE ''\D83D\DD34\D83D\DD34\D83D\DD34 \D83D\DD34\D83D\DD34\D83D\DD34\D83D\DD34\0648\0636\0639 \0627\0644\0645\0644\0641 \063A\064A\0631 \0639\0627\062F\064A \0627\0644\0631\062C\0627\0621 \0627\0644\062A\062B\0628\062A'''),
'    ',
'   ',
'    end as stat,',
'    CASE  ',
'        WHEN sysdate - cc.date_ouverture_des_plis > 30 THEN ''u-color-39''',
'        WHEN  sysdate - cc.date_ouverture_des_plis > 20 and  sysdate - cc.date_ouverture_des_plis < 30  THEN ''u-color-37''',
'        WHEN sysdate - cc.date_ouverture_des_plis > 0 and  sysdate - cc.date_ouverture_des_plis < 20  THEN ''u-color-35''',
'        ELSE ''u-color-44-contrast''',
'    END AS COLOR_CELL,',
'   CASE  ',
unistr('        WHEN sysdate - cc.date_ouverture_des_plis > 30 THEN ''\D83D\DD34 \0639\0627\062C\0644 \062C\062F\0627\064B'''),
unistr('        WHEN  sysdate - cc.date_ouverture_des_plis > 20 and  sysdate - cc.date_ouverture_des_plis < 30  THEN ''\D83D\DFE0 \0645\0647\0645'''),
unistr('        WHEN sysdate - cc.date_ouverture_des_plis > 10 and  sysdate - cc.date_ouverture_des_plis < 20  THEN ''\D83D\DD35 \0639\0627\062F\064A'''),
unistr('        ELSE ''\26AA \0639\0627\062F\064A'''),
'    END AS IMPORTANCETEXT,',
'    CASE',
'        WHEN  sysdate - cc.date_ouverture_des_plis > 30 THEN ''fa-fire fa-1x fa-stop-circle fa-anim-horizontal-shake fa-lg''',
'        WHEN  sysdate - cc.date_ouverture_des_plis > 20 and  sysdate - cc.date_ouverture_des_plis < 30 THEN ''fa-alarm-snooze fa-anim-spin-step fam-information fam-is-warning fa-lg''',
'        WHEN sysdate - cc.date_ouverture_des_plis > 10 and  sysdate - cc.date_ouverture_des_plis < 20 THEN ''fa-sticky-note text-info''',
'        ELSE ''fa-circle text-muted''',
'    END AS CARDICON,',
'       CASE',
'        WHEN sysdate - cc.date_ouverture_des_plis > 30',
'            THEN ''near''',
'        ELSE ''''',
'    END AS BADGE_CLASS,',
'    cc.creer_par,',
unistr('    cc."DATE_CR\00C9ATION",'),
'    cc.programme_de_lancement',
'FROM cc',
'WHERE cc.status = 5',
'',
'  AND NOT EXISTS (',
'        SELECT 1',
'        FROM contrats ct',
'        WHERE ct.id_cc = cc.id',
'  )',
'',
'',
'/*',
'SELECT',
'    ID,',
'    NOTE_TITLE   AS NOTETITLE,',
'    NOTE_DETAILS AS NOTEDETAILS,',
'    REMINDER_DATETIME,',
'    TO_CHAR(REMINDER_DATETIME, ''DD Mon - HH24:MI'') AS REMINDERFMT,',
'',
unistr('    -- \0623\064A\0642\0648\0646\0629 \0648\0644\0648\0646 \062D\0633\0628 \0627\0644\0623\0647\0645\064A\0629'),
'    CASE IMPORTANCE_LEVEL',
'        WHEN 3 THEN ''fa-bell text-danger''',
'        WHEN 2 THEN ''fa-exclamation-triangle text-warning''',
'        WHEN 1 THEN ''fa-sticky-note text-info''',
'        ELSE ''fa-circle text-muted''',
'    END AS CARDICON,',
'',
unistr('    -- \0646\0635 \0627\0644\0623\0647\0645\064A\0629'),
'    CASE IMPORTANCE_LEVEL',
unistr('        WHEN 3 THEN ''\D83D\DD34 \0639\0627\062C\0644 \062C\062F\0627\064B'''),
unistr('        WHEN 2 THEN ''\D83D\DFE0 \0645\0647\0645'''),
unistr('        WHEN 1 THEN ''\D83D\DD35 \0639\0627\062F\064A'''),
unistr('        ELSE ''\26AA \0639\0627\062F\064A'''),
'    END AS IMPORTANCETEXT,',
'',
unistr('    -- \0646\0635 \0627\0644\0634\0631\064A\0637: \0627\0644\062F\0642\0627\0626\0642 + \0627\0644\0646\0633\0628\0629 \0627\0644\0645\0626\0648\064A\0629'),
'    CASE',
'        WHEN REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440) <= SYSDATE',
'             AND REMINDER_DATETIME >= SYSDATE - 0.1/24 THEN',
unistr('             ''\D83D\DD04 \062A\0630\0643\064A\0631 \0645\0633\062A\0645\0631 ('' || ROUND('),
'                 LEAST(100, GREATEST(0,',
'                   (1 - (((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - SYSDATE) /',
'                         ((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - TRUNC(SYSDATE)))) * 100',
'                 ))',
'             ) || ''%)''',
'        WHEN REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440) <= SYSDATE THEN',
unistr('             ''\2705 \0627\0646\062A\0647\0649 (100%)'''),
'        ELSE',
'             FLOOR(((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - SYSDATE) * 1440)',
'             || '' Minutes (''',
'             || ROUND(',
'                 LEAST(100, GREATEST(0,',
'                   (1 - (((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - SYSDATE) /',
'                         ((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - TRUNC(SYSDATE)))) * 100',
'                 ))',
'             )',
'             || ''%) ''',
'    END AS MINUTES_LEFT,',
'',
unistr('    -- \0646\0633\0628\0629 \0627\0644\062A\0642\062F\0645 (0-100) \0645\062A\0627\062D\0629 \0644\0648 \0627\062D\062A\062C\062A\0647\0627 \0644\0627\062D\0642\0627\064B'),
'    LEAST(100, GREATEST(0,',
'        (1 - (((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - SYSDATE) /',
'              ((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - TRUNC(SYSDATE)))) * 100',
'    )) AS PROGRESS_PERCENT,',
'',
unistr('    -- \0643\0644\0627\0633 \0625\0636\0627\0641\064A \0644\0648 \0623\0631\062F\062A \062A\0623\062B\064A\0631 \062E\0627\0635 \0639\0646\062F \0627\0644\0627\0642\062A\0631\0627\0628 (\0627\062E\062A\064A\0627\0631\064A)'),
'    CASE',
'        WHEN ((REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440)) - SYSDATE) * 1440 <= 30',
'            THEN ''near''',
'        ELSE ''''',
'    END AS BADGE_CLASS,',
'',
unistr('    -- \0644\0648\0646 \0634\0631\064A\0637 \0627\0644\062A\0642\062F\0645 \062D\0633\0628 \0627\0644\0623\0647\0645\064A\0629 (\0644\0648 \0627\0633\062A\062E\062F\0645\062A\0647 \062F\0627\062E\0644 CSS)'),
'    CASE IMPORTANCE_LEVEL',
'        WHEN 3 THEN ''bg-danger''',
'        WHEN 2 THEN ''bg-warning''',
'        WHEN 1 THEN ''bg-info''',
'        ELSE ''bg-secondary''',
'    END AS PROGRESS_COLOR',
'',
'FROM USER_NOTES',
'WHERE USER_ID = :P32_ROLE',
'   AND NOT (IS_SENT = ''Y''',
'           AND REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440) < SYSDATE -1)',
'ORDER BY IMPORTANCE_LEVEL DESC, REMINDER_DATETIME ASC;',
'*/',
''))
