'function calculer() {',
'    var debut  = apex.item(''P47_DATE_DEBUT'').getValue();',
'    var fin    = apex.item(''P47_DATE_FIN'').getValue();',
'    var avant  = parseFloat(apex.item(''P47_SOLDE_AVANT'').getValue()) || 0;',
'    var feries = parseInt(apex.item(''P47_NBR_FERIES'').getValue()) || 0;',
'    var tc = apex.item(''P47_TYPE_CONGE'').getValue();',
'if (tc  ===  ''SOLDE''){',
'    if (debut && fin) {',
'        var d1 = new Date(debut.split(''/'').reverse().join(''-''));',
'        var d2 = new Date(fin.split(''/'').reverse().join(''-''));',
'        var diff = Math.round((d2 - d1) / (1000 * 60 * 60 * 24));',
'        if (diff >= 0) {',
'            apex.item(''P47_NBR_JOURS'').setValue(diff);',
'            var soldeApres = avant + feries - diff;',
'            apex.item(''P47_SOLDE_APRES'').setValue(soldeApres.toFixed(0));',
'        }',
'    }',
'',
'else {',
'    if (debut && fin) {',
'        var d1 = new Date(debut.split(''/'').reverse().join(''-''));',
'        var d2 = new Date(fin.split(''/'').reverse().join(''-''));',
'        var diff = Math.round((d2 - d1) / (1000 * 60 * 60 * 24));',
'        if (diff >= 0) {',
'            apex.item(''P47_NBR_JOURS'').setValue(diff);',
'             apex.item(''P47_SOLDE_APRES'').setValue(avant.toFixed(0));',
'           ',
'        }',
'    }',
'}',
'}',
'}',
'calculer();'))
,p_client_condition_type=>'NOT_NULL'
,p_client_condition_element=>'P47_DATE_DEBUT'
,p_created_on=>wwv_flow_imp.dz('20260429101434Z')
,p_updated_on=>wwv_flow_imp.dz('20260522150808Z')
,p_created_by=>'CHIRAZ'
,p_updated_by=>'CHIRAZ'
);
