,p_name=>'Cal_nbr_h'
,p_event_sequence=>5
,p_triggering_element_type=>'REGION'
,p_triggering_region_id=>wwv_flow_imp.id(18650504874812761)
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
