wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(19772074265593137)
,p_event_id=>wwv_flow_imp.id(18881141580266986)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'COLUMN'
,p_affected_elements=>'DEBUT,FIN,NBR_H'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'setTimeout(function () {',
'    var view  = apex.region("GRILLE").call("getViews", "grid");',
'    if (!view || !view.model) return;',
'    ',
'    var model = view.model;',
'',
'    model.forEach(function(record){',
'        if (record.meta && record.meta.deleted) {',
'            return;',
'        }',
'',
'        var debut = model.getValue(record, "DEBUT");',
'        var fin   = model.getValue(record, "FIN");',
'',
'        if (!debut || !fin) {',
'            return;',
'        }',
'',
unistr('        // V\00E9rification du format avant calcul'),
'        var regex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;',
'        if (!regex.test(debut) || !regex.test(fin)) {',
'            return;',
'        }',
'',
'        var d = debut.split(":");',
'        var f = fin.split(":");',
'',
'        var debutMin = parseInt(d[0], 10) * 60 + parseInt(d[1], 10);',
'        var finMin   = parseInt(f[0], 10) * 60 + parseInt(f[1], 10);',
'',
'        var diffMinutes = finMin - debutMin;',
'',
unistr('        // Gestion du passage \00E0 minuit en JavaScript \00E9galement'),
'        if (diffMinutes < 0) {',
'            diffMinutes = diffMinutes + (24 * 60);',
'        }',
'',
unistr('        // Traduction exacte en JavaScript du calcul de notre trigger (Arrondi \00E0 0.5 pr\00E8s)'),
'        var rounded = Math.round((diffMinutes / 60) * 2) / 2;',
'',
unistr('        // Mise \00E0 jour de la colonne NBR_H \00E0 l''\00E9cran si la valeur calcul\00E9e est diff\00E9rente'),
'        if (model.getValue(record, "NBR_H") != rounded) {',
'            model.setValue(record, "NBR_H", rounded);',
'            model.metadataChanged(record);',
'        }',
'    });',
'}, 150);'))
,p_updated_on=>wwv_flow_imp.dz('20260522145430Z')
,p_updated_by=>'CHIRAZ'
);
