wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(74585209380179929420)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Enregistrer le style de th\00E8me')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P10020_DESKTOP_THEME_STYLE_ID is not null then',
'    for l_theme in (select theme_number',
'                      from apex_application_themes',
'                     where application_id = :app_id',
'                       and ui_type_name   = ''DESKTOP''',
'                       and is_current     = ''Yes'')',
'    loop',
'        apex_util.set_current_theme_style (',
'            p_theme_number   => l_theme.theme_number,',
'            p_theme_style_id => :P10020_DESKTOP_THEME_STYLE_ID',
'            );',
'    end loop;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>unistr('Param\00E8tres d''apparence de l''application enregistr\00E9s.')
,p_internal_uid=>61391566285762275299
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(74585209731321929420)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Enregistrer la pr\00E9f\00E9rence de style de l''utilisateur final')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_enabled boolean := case when :P10020_END_USER_STYLE = ''Yes'' then true else false end;',
'begin',
'    for l_theme in ( select ui.theme_number',
'                       from apex_application_themes t,',
'                            apex_appl_user_interfaces ui',
'                      where ui.application_id = t.application_id',
'                        and ui.theme_number   = t.theme_number',
'                        and t.application_id  = :APP_ID',
'                        and t.ui_type_name    = ''DESKTOP''',
'                        and t.is_current      = ''Yes'' )',
'    loop',
'        if l_enabled then',
'            apex_theme.enable_user_style (',
'                p_application_id => :APP_ID,',
'                p_theme_number   => l_theme.theme_number );',
'        else',
'            apex_theme.disable_user_style (',
'                p_application_id => :APP_ID,',
'                p_theme_number   => l_theme.theme_number );',
'            apex_theme.clear_all_users_style(:APP_ID);',
'        end if;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>unistr('Param\00E8tres d''apparence de l''application enregistr\00E9s.')
,p_internal_uid=>61391566636904275299
);
end;
